INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (27911871, 'Wynton Marsalis Plays Louis Armstrong''s Hot Fives And Hot Sevens', 2023, 'US', '2023-08-04', '04 Aug 2023', 'Recorded live on September 30, 2006 at Jazz at Lincoln Center''s Frederick P. Rose Hall.  Recorded in the 1920s, Louis Armstrong''s Hot Fives and Hot Sevens sides are still hailed as some of the greatest and most influential jazz sessions ever captured' + CHAR(59) + ' musicians obsess over their warmth, wit, and joy to this day. A new live recording by Wynton Marsalis a?? another acclaimed New Orleans trumpetera?? reimagines classics from those sessions like "Basin Street Blues," "St. James Infirmary," and "Heebie Jeebies" for a whole new generation of audiences. Performed in 2006, Wynton Marsalis Plays Louis Armstrong''s Hot Fives and Sevens assembles an all-star band of Marsalis collaborators (like trombonist Wycliffe Gordon and pianist Jon Batiste) who, together, recreate the magic of Armstrong''s seminal ensembles. There are perhaps no better interpreters of Armstrong''s legacy than Marsalis and his fellow musicians' + CHAR(59) + ' and, through transposing the timeless music of the 1920s to the 21st century, these expert players deliver technically flawless performances and prove Marsalis'' assertion that all eras of jazz are integrated.', '"Jazz"', '"Dixieland"', '2023-08-08T01:04:24-07:00', '2023-08-08T04:04:21-07:00', NULL, NULL, 'https://www.discogs.com/release/27911871-Wynton-Marsalis-Wynton-Marsalis-Plays-Louis-Armstrongs-Hot-Fives-And-Hot-Sevens', 'https://i.discogs.com/sGJ6l1xM1Z81-xFhjLTs1ZmI4UH91OdSdQUONDd9g6A/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTI3OTEx/ODcxLTE2OTE0ODE4/NjUtMTc2OS5wbmc.jpeg', '[{"name":"Jazz At Lincoln Center","catno":""