INSERT INTO AlbumContainsArtist (discogs_artist_id, discogs_release_id, is_main) VALUES (251769, 1351437, 1);
INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (2223190, 'The Hawk Flies', 1973, NULL, NULL, NULL, 'The material on Sides A and B was originally issued as 78 rpm singles. "Flyin'' Hawk" and "Driftin'' On A Reed" were on the Joe Davis label (8250), recorded 19 October 1944' + CHAR(59) + ' "On The Bean" and "Recollections" were Joe Davis 8251, recorded 19 October 1944' + CHAR(59) + ' "Cocktails For Two" were Sonora 3024 (but the first take of "Bean And The Boys" was released for the first time on the 1970 Prestige reissue album PR 7824), recorded Dec. 1946' + CHAR(59) + ' "I Mean You" and "You Go To My Head" were Sonora 3017, recorded Dec. 1946. "Bay-U-Bah" and "Sophisticated Lady" were French Vogue 5024, recorded 21 Dec. 1949' + CHAR(59) + ' "Sih-Sah" and "Bean''s Talking Again" were French Vogue 5024 (?), recorded 21 Dec. 1949. "Ruby My Dear" was originally issued on "Monk''s Music" (Riverside 242), recorded 21 June 1957. The other material on Sides C and D was originally issued as "The Hawk Flies High" (Riverside 233), recorded 12 & 15 March 1957.', '"Jazz"', '["Bop","Hard Bop"]', NULL, NULL, 1896213, 'https://api.discogs.com/masters/1896213', 'https://www.discogs.com/master/1896213-Coleman-Hawkins-The-Hawk-Flies', NULL, NULL, NULL, '[{"type":"primary","uri":"https://i.discogs.com/9j8BbKSsNoyblaToSNfI5iBkQIGyBh2rBvIGMrxjCRs/rs:fit/g:sm/q:90/h:231/w:218/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIyMjMx/OTAtMTMzMTE4NTgx/NC5qcGVn.jpeg","resource_url":"https://i.discogs.com/9j8BbKSsNoyblaToSNfI5iBkQIGyBh2rBvIGMrxjCRs/rs:fit/g:sm/q:90/h:231/w:218/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIyMjMx/OTAtMTMzMTE4NTgx/NC5qcGVn.jpeg","uri150":"https://i.discogs.com/q9OJEw2F93HieZo3Q9hjQS-p8wYe0Qj4KvHLfTBHAaw/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGF