INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (4681916, 'Hawk', 0, 'US', NULL, NULL, 'Apparent private/hobby label release. Date uncertain, probably 1970s or early 1980s. Consists of two radio broadcasts of big-band swing music featuring Hawkins, likely from the 1930s, possibly with Fletcher Henderson''s orchestra. Occasional voice-overs by announcers. Sound quality is mixed, with S2 generally of higher quality than S1.  Jacket front includes text: "STEREO-MONO-HIRSCHGUARD PROCESS." Recording appears to be mono.  Jacket has light pink front cover, image of Hawkins and of a hawk, track listings. Logo in upper right of reel-to-reel recorder and LP, title "McKoon''s Menagerie," cat# HAWK:257169. Text at bottom reads: "Collector''s Issue Especially For ''Hawk''s'' Good Pal Ronald And His Pals. Altamont, Oregon."  Jacket rear is blank.  Labels are light green with black print, hawk image, track listings in green type against black background.', '"Jazz"', '"Swing"', '2013-06-24T06:49:40-07:00', '2025-07-01T13:24:14-07:00', NULL, NULL, 'https://www.discogs.com/release/4681916-Coleman-Hawkins-Hawk', 'https://i.discogs.com/GGD8v0eMftYJky0yFa-3b5FBDlGtk5SBLhyPhc9VaM4/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTQ2ODE5/MTYtMTUyNDUwMzQz/My0zMjEyLmpwZWc.jpeg', NULL, '{"name":"Coleman Hawkins","anv":"","join":"","role":"Tenor Saxophone","tracks":"","id":251769,"resource_url":"https://api.discogs.com/artists/251769"}', '[{"type":"primary","uri":"https://i.discogs.com/uLZwoKwXBb3EKzNUDs0lDH9cVSD_Cf6ZrTTyGCQ5jvE/rs:fit/g:sm/q:90/h:600/w:600/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTQ2ODE5/MTYtMTUyNDUwMzQz/My0zMjEyLmpwZWc.jpeg","resource_url":"https://i.discogs.com/uLZwoKwXBb3EKzNUDs0lDH9cVSD_Cf6ZrTTyGCQ5jvE/rs:fit/g:sm/q:90/h:600/w:600/cz