INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (17697025, 'Coleman Hawkins Quintet Featuring Teddy Wilson At The Piano', 0, 'US', NULL, NULL, 'This release is a 3-LP collected set of previously issued Coleman Hawkins releases on the Keynote Recordings label of catalog numbers 609 A/B, 611 A/B and 612 A/B.  There are only three leaves in the album cover so release 610 A/B is not missing, just not included in this 3-disc set.  The spine has catalog # K124 embossed on it while the interior cover of the sleeve has only "Album No. 124" printed on it.  Each individual disc bears their own original catalog numbers.  K609  S'' Wonderful & I only Have Eyes For You recorded January 31, 1944, New York City. K611  Flame Thrower & Night and Day and K612 Imagination & Cattin'' at Keynote recorded February 17, 1944, New York City. These are presumably released in 1944 although this can''t be verified at the moment of this writing.  See https://www.jazzdisco.org/mercury-records/discography-1941-1944/ ', '"Jazz"', '"Swing"', '2021-03-05T00:18:46-08:00', '2023-03-17T11:32:30-07:00', NULL, NULL, 'https://www.discogs.com/release/17697025-Coleman-Hawkins-Coleman-Hawkins-Quintet-Teddy-Wilson-Coleman-Hawkins-Quintet-Featuring-Teddy-Wilson-', 'https://i.discogs.com/x8nu9wvnkYKsIar58hC1KcRafBL29MxVTk562xwRaqU/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTE3Njk3/MDI1LTE2MTQ5MzIz/MjgtNTYxMC5qcGVn.jpeg', '[{"name":"Allied Printing New York","catno":"","entity_type":"19","entity_type_name":"Printed By","id":2102860,"resource_url":"https://api.discogs.com/labels/2102860","thumbnail_url":"https://i.discogs.com/DXyvkN7dMfgcIHP6qkmdP6d4xgglJArx1-0f3V65ids/rs:fit/g:sm/q:90/h:416/w:600/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9MLTIxMDI4/NjAtMTYzMzY1MjIz/Ny0yOTk