INSERT INTO AlbumContainsArtist (discogs_artist_id, discogs_release_id, is_main) VALUES (266136, 3687899, 1);
INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (2313859, 'Don''t Send Me No Flowers', 1968, NULL, NULL, NULL, 'Of the many obscure projects Jimmy Page was associated with prior to Led Zeppelin, one of the most notable was a studio session he recorded live alongside noted keyboardist Brian Auger, and famed bluesman, Sonny Boy Williamson. The session took place at IBC Studios on January 28, 1965. Those present at the session included, Jimmy Page on guitar, Brian Auger on organ, Ricky Brown on bass Mickey Waller on drums along with Joe Harriot & Alan Skidmore on saxophone, and Sonny Boy taking up vocal and harmonica. While doing press for the documentary film "It Might Get Loud" Jimmy Page also recalled the session with Sonny Boy Williamson: "The one that was done live with The Yardbirds hadna??t come out. It was our manager who called me. I was a studio musician, at the time, and Sonny Boy was living in his flat. Somebody told me once that they went to the house and they heard Sonny Boy plucking a live chicken. I dona??t know how true that was. That didna??t happen when I was there. Sonny Boy and myself rehearsed these numbers in the managera??s flat and, by the time we got into the studio a couple days later, Sonny Boy had forgotten all of the arrangements of what we were going to do. It was cool. Good music comes out of that." (Corbin, Pageia Obscura)', '"Blues"', NULL, NULL, NULL, 90617, 'https://api.discogs.com/masters/90617', 'https://www.discogs.com/master/90617-Sonny-Boy-Williamson-2-With-Brian-Auger-The-Trinity-Joe-Harriott-Alan-Skidmore-Jimmy-Page-Dont-Send-', NULL, NULL, NULL, '[{"type":"primary","uri":"https://i.discogs.com/_m8ZLpe68tGIDHHl1lTv0QsyuVyup95tlGludQ70GkU/rs:fit/g:sm/q:90/h:600/w:594/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIzMT