INSERT INTO AlbumContainsArtist (discogs_artist_id, discogs_release_id, is_main) VALUES (284314, 708809, 1);
INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (2352676, 'Bells', 1965, NULL, NULL, NULL, 'A NOTE ON US PRESSINGS  This particular release was issued in a bewildering amount of variations, numbering 20 or more. This title was on catalogue until 1974. To identify your copy, please check the following confirmed variations:  Front cover colours: Black with ochre lettering Black with white lettering Red with blue lettering Orange with maroon lettering White with red lettering White with black lettering  Front cover content: A ''''stereo'''' wording can appear either in the rim text on front or as a small caption underneath the title. Some copies have the ''''stereo'''' rim text blotted out. Appearing in the rim text does NOT automatically mean your copy plays stereo, please see the runout remarks far below.  The rim text may mention an address in New York, either: 180 Riverside Drive 156 5th Avenue or 300 West 55th St  Back cover colours: White with violet lettering White with blue lettering White with black lettering Black with yellow lettering Blank (no printing at all)  Back cover content: Blank Down Beat review and no mentioning of other releases. Down Beat review and mentioning of other releases up till 1020. A repeat of the front cover.  The liner notes may mention an address in New York, either: 180 Riverside Dr. 300 West 55 Street or 290 West End Avenue   Label colour and content No label at all A green duotone of a portrait of Ayler/ back side flat white A green duotone of a portrait of Ayler/ back side flat orange A green duotone of a portrait of Ayler/ back side with large ESP logo. A liver-colored duotone of a portrait of Ayler/ back side with large ESP logo. pink blank labels on both sides orange blank labels on both sides   Vinyl colour: Clear with red silk screened lettering Clear without any lettering Gold translucent with red silk screened lettering Violet with white silk screened lettering Grey marbled with red silk screened lettering Grey marbled with white silk screened lettering and a green pattern. Grey translucent with white silk screened lettering Blue with white silk screened lettering Maroon with white silk screened lettering Blue/black splash with white silk screened lettering Yellow translucent without any lettering Orange translucent without any lettering Black without any lettering Red translucent without any lettering  Early issues may have an inner sleeve with a printed article titled ''''They don''t call it jazz''''.  Runout etchings may indicate whether it is stereo (ESPS-1010) or mono (ESPM-1010). Mono copies are much rarer then stereo ones. Some etchings additionally contain the exact pressing date.', '"Jazz"', '"Free Jazz"', NULL, NULL, 25524, 'https://api.discogs.com/masters/25524', 'https://www.discogs.com/master/25524-Albert-Ayler-Bells', NULL, NULL, NULL, '[{"type":"primary","uri":"https://i.discogs.com/kA6QSTLQ_UQtR1cXVRcjtLSqqE46QDqoq1pTsxYmHYU/rs:fit/g:sm/q:90/h:549/w:550/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIzNTI2/NzYtMTI3ODk1OTk1/NS5qcGVn.jpeg","resource_url":"https://i.discogs.com/kA6QSTLQ_UQtR1cXVRcjtLSqqE46QDqoq1pTsxYmHYU/rs:fit/g:sm/q:90/h:549/w:550/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIzNTI2/NzYtMTI3ODk1OTk1/NS5qcGVn.jpeg","uri150":"https://i.discogs.com/vYBEU-9cdn61dkPig9Jg5sFg1vHK0TQXVOdiUSjleLc/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIzNTI2/NzYtMTI3ODk1OTk1/NS5qcGVn.jpeg","width":550,"height":549},{"type":"secondary","uri":"https://i.discogs.com/d4evZ1mvIcETCCOwWSc04O2P0abHvYxBBKmEars0Ytg/rs:fit/g:sm/q:90/h:294/w:301/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIzNTI2/NzYtMTI3ODk2MDEy/Ny5qcGVn.jpeg","resource_url":"https://i.discogs.com/d4evZ1mvIcETCCOwWSc04O2P0abHvYxBBKmEars0Ytg/rs:fit/g:sm/q:90/h:294/w:301/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIzNTI2/NzYtMTI3ODk2MDEy/Ny5qcGVn.jpeg","uri150":"https://i.discogs.com/KsSH5o3A3E3bu0pwpcwF_NS65V1FjwdG2P85kR0g7pg/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTIzNTI2/NzYtMTI3ODk2MDEy/Ny5qcGVn.jpeg","width":301,"height":294}]', NULL, '{"position":"A","type_":"track","title":"Bells","duration":""}', '[{"uri":"https://www.youtube.com/watch?v=C51oEXySfGQ","title":"Bells- Albert Ayler- Town Hall","description":"Recorded May 1, 1965, Town Hall, NYC. Albert Ayler-ts, Donald Ayler-tpt, Charles Tyler-as, Lewis Worrell-bass, Sunny Murray-dms","duration":1206,"embed":true},{"uri":"https://www.youtube.com/watch?v=XGq5-n_AL-0","title":"Albert Ayler a?�- Bells (1965) FULL ALBUM","description":"ESP Disk a?�a?? 1010 (US, 1965)\\nhttps://www.discogs.com/Albert-Ayler-Bells/release/2352676\\n\\nA. Bells\\n\\nRecorded live at Town Hall, May 1, 1965 \\n\\nPersonnel:\\nAlbert Ayler - tenor saxophone\\nDonald Ayler - trumpet\\nCharles Tyler - alto saxophone\\nLewis Worrell -","duration":1206,"embed":true}]', NULL, NULL);
