INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (676516, 'I Giganti Del Jazz Vol. 6', 1980, NULL, NULL, NULL, '"OCDC", which stands probably for ''Ornette Coleman Don Cherry'' is indeed "Togetherness One - First Movement" + "Togetherness One - Second Movement" (music stops between at 5:08) from Don Cherry - Togetherness, recorded Spring 1965. Aldo Romano is the uncredited drummer, not Jacques Thollot who is miscredited.  "Third Movement" is indeed "Togetherness One - Third Movement" also from Don Cherry - Togetherness, recorded Spring 1965, with uncredited Aldo Romano as drummer, and not Jacques Thollot who is miscredited.  "Ghosts" can be heard as 6th track of Albert Ayler - LA�rrach, Paris 1966, it was recorded live by Radio France at Salle Pleyel during Paris Jazz Festival on November 13th, 1966 according to this Hatology reissue. Don Ayler, on trumpet, Bill Folwell on bass and Beaver Harris on drums, all uncredited on release. Not Norman Howard, Earle Henderson, Henry Grimes and Sunny Murray who are miscredited on cover.  "If We Only Knew" comes from John Handy - Recorded Live At The Monterey Jazz Festival, recorded September 18, 1965 with Michael White on violin, Jerry Hahn on guitar, Don Thompson on bass and Terry Clarke, all uncredited on release. Not Michael Sampson, George Tucker, Bobby Fulhordt who are miscredited. Barcode and Other Identifiers', '"Jazz"', '["Free Jazz","Soul-Jazz","Modal"]', NULL, NULL, 400655, 'https://api.discogs.com/masters/400655', 'https://www.discogs.com/master/400655-Gato-Barbieri-Don-Cherry-Albert-Ayler-John-Handy-I-Giganti-Del-Jazz-Vol-6', NULL, NULL, NULL, '[{"type":"primary","uri":"https://i.discogs.com/o_O10CTkN0Jsck9FQMRK-kp0G7tWpd6nYfWVSRkrq7I/rs:fit/g:sm/q:90/h:593/w:600/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy