INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (1237102, '9 Compositions (Iridium) 2006', 2007, 'US', '2007-04-03', '03 Apr 2007', 'Documenting what Time Out New York called "Last Spring''s epochal run" at New York''s Iridium Jazz Club with his 12+1tet. Described by Braxton as "The point of definition in my work thus far..." these concerts featured the world premieres of Compositions 350 through 358, the final works in his Ghost Trance Music series, recorded over the course of this rare four-night stand on an American stage. Recorded live in March 16-19, 2006 at Iridium Jazz Club, New York.  Comes with a 56-Page Booklet. Also available for MP3 download on the label''s page.', '"Jazz"', '"Free Jazz"', '2008-02-13T07:57:07-08:00', '2025-10-31T13:01:25-07:00', NULL, NULL, 'https://www.discogs.com/release/1237102-Anthony-Braxton-9-Compositions-Iridium-2006', 'https://i.discogs.com/Mm1B-K2AwAXDf5ab4UmQcIBCoOdUr5H4aZ1QGbK1CPk/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTEyMzcx/MDItMTU2ODEwODcw/NS0xOTQ0LmpwZWc.jpeg', '{"name":"Iridium Jazz Club","catno":"","entity_type":"23","entity_type_name":"Recorded At","id":753915,"resource_url":"https://api.discogs.com/labels/753915","thumbnail_url":"https://i.discogs.com/8S53ehnWNNjaDpIdg4CbQOjN-BSU-G5yTUm1Wk3j6eE/rs:fit/g:sm/q:90/h:244/w:351/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9MLTc1Mzkx/NS0xNjQwOTMzNTU0/LTc1MzkuanBlZw.jpeg"}', '[{"name":"Nicole Mitchell","anv":"","join":"","role":"Alto Flute, Bass Flute, Piccolo Flute, Voice","tracks":"","id":425005,"resource_url":"https://api.discogs.com/artists/425005"},{"name":"Steve Lehman","anv":"","join":"","role":"Alto Saxophone, Sopranino Saxophone","tracks":"","id":979467,"resource_url":"https://api.discogs.com/artists/979467"},{"name":"James 