INSERT INTO Album (release_id, title, year, country, released, released_formatted, notes, genres, styles, date_added, date_changed, master_id, master_url, uri, thumb, companies, extra_artists, images, labels, tracklist, videos, rating_count, rating_average) VALUES (1266732, 'Solo (Pisa) 1982', 2007, 'UK', '2007-05-00', 'May 2007', 'Music by Anthony Braxton (Synthesis Music / BMI) unless otherwise indicated in Europe published by Alissa Publishing / PRS' + CHAR(59) + ' Recording engineer unknown  Braxton''s solo live concert in Italy, featuring seven original compositions and four jazz standards, including John Coltrane''s ''Giant Steps.'' On the last track, a colossal ovation is captured in its entirety, described by Steve Day in the liner notes: "They [audience] literally become the music, setting up a seven minutes coda of appreciative stomping, whistling, howling harmony vocals, improvised rhythms tracks, and general mayhem' + CHAR(59) + ' shaking down the melody and the intervals, creating an additional bonus track."', '"Jazz"', '["Free Jazz","Free Improvisation","Avant-garde Jazz"]', '2008-03-10T16:56:56-07:00', '2025-08-11T15:36:44-07:00', NULL, NULL, 'https://www.discogs.com/release/1266732-Anthony-Braxton-Solo-Pisa-1982', 'https://i.discogs.com/KWDax16VPpnV0cttbU6E3ITDG4AkxoqCHtwUxCQXSyk/rs:fit/g:sm/q:40/h:150/w:150/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9SLTEyNjY3/MzItMTQyODc4MTg3/Ni0xMjk2LmpwZWc.jpeg', '[{"name":"Golden Years Of New Jazz","catno":"","entity_type":"14","entity_type_name":"Copyright (c)","id":42583,"resource_url":"https://api.discogs.com/labels/42583","thumbnail_url":"https://i.discogs.com/IYOi92OQCffg4vg4czmTR-cjqtsi5jP36t4plbSUxVk/rs:fit/g:sm/q:90/h:200/w:200/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9MLTQyNTgz/LTE1MDY2OTg4MDct/OTcxMi5qcGVn.jpeg"},{"name":"Golden Years Of New Jazz","catno":"","entity_type":"13","entity_type_name":"Phonographic Copyright (p)","id":42583,"resource_url":"https://api.discogs.com/labels/42583","thumbnail_url":"h